def resolve_torch_cuda_variant_config(variant: str | None = None) -> dict[str, Any]:
    from .device import resolve_torch_cuda_variant

    key = str(variant or resolve_torch_cuda_variant() or "cu126").strip().lower()
    if key not in TORCH_CUDA_VARIANT_CONFIG:
        if key.startswith("cu13"):
            key = "cu130"
        elif key.startswith("cu12"):
            key = "cu128" if key != "cu126" else "cu126"
        else:
            key = "cu126"
    return TORCH_CUDA_VARIANT_CONFIG[key]


class MirrorStallError(RuntimeError):
    """Raised when a mirror transfer makes no progress for too long."""


class MirrorTooSlowError(MirrorStallError):
    """Raised when a mirror transfers data but far too slowly to finish in time."""


def transfer_should_abort(
    *,
    elapsed_sec: float,
    session_bytes: int,
    last_progress_age_sec: float,
    stall_sec: float = DOWNLOAD_STALL_SEC,
    min_bps: float = DOWNLOAD_MIN_BPS,
    warmup_sec: float = DOWNLOAD_SLOW_WARMUP_SEC,
    max_sec: float = DOWNLOAD_MIRROR_MAX_SEC,
    slow_min_bytes: int = DOWNLOAD_SLOW_MIN_BYTES,
) -> str | None:
    """
    Return an abort reason, or None if the transfer may continue.

    Distinguishes hard stall (no new bytes) from trickle that would burn ~30 min.
    """
    if elapsed_sec >= max_sec:
        return f"STALL: 单镜像超过 {int(max_sec)} 秒上限"
    if last_progress_age_sec >= stall_sec:
        return f"STALL: 下载停滞超过 {int(stall_sec)} 秒"
    if (
        elapsed_sec >= warmup_sec
        and session_bytes >= slow_min_bytes
        and session_bytes / max(elapsed_sec, 0.001) < min_bps
    ):
        bps = session_bytes / max(elapsed_sec, 0.001)
        return (
            f"STALL: 下载过慢（约 {bps / 1024:.0f} KB/s < {min_bps / 1024:.0f} KB/s），切换镜像"
        )
    return None


def is_mirror_http_deny(text: str) -> bool:
    """True when pip/download output looks like HTTP deny or stall."""
    return bool(_RE_MIRROR_HTTP_DENY.search(str(text or "")))


def note_mirror_denied(host: str) -> None:
    h = str(host or "").strip().lower()
    if h:
        _demoted_mirror_hosts.add(h)


def clear_demoted_mirrors() -> None:
    _demoted_mirror_hosts.clear()


def demoted_mirror_hosts() -> frozenset[str]:
    return frozenset(_demoted_mirror_hosts)


def packages_base_url(index_url: str) -> str:
    """Map a PyPI simple index URL to its packages/ file root."""
    u = str(index_url or "").strip().rstrip("/")
    host = (urlparse(u).hostname or "").lower()
    if host in ("pypi.org", "pypi.python.org") or u.endswith("://pypi.org/simple"):
        return "https://files.pythonhosted.org/packages"
    if u.endswith("/simple"):
        return u[: -len("/simple")] + "/packages"
    return u + "/packages"


def wheel_url_for(index_url: str, rel_path: str) -> str:
    base = packages_base_url(index_url).rstrip("/")
    rel = str(rel_path or "").lstrip("/")
    return f"{base}/{rel}"


def known_wheel_rel(package_name: str) -> str:
    key = str(package_name or "").strip().lower().replace("_", "-")
    return KNOWN_WHEEL_RELS.get(key, "")


def known_wheel_version(package_name: str) -> str:
    """Parse version from the pinned known-wheel filename, or ''."""
    rel = known_wheel_rel(package_name)
    if not rel:
        return ""
    fname = str(rel).rsplit("/", 1)[-1]
    if not fname.endswith(".whl"):
        return ""
    stem = fname[: -len(".whl")]
    # pep 427: {distribution}-{version}(-{build})?-{python}-{abi}-{platform}.whl
    parts = stem.split("-")
    if len(parts) < 5:
        return ""
    dist_and_ver = parts[:-3]
    if len(dist_and_ver) >= 3 and dist_and_ver[-1].isdigit():
        return dist_and_ver[-2]
    if len(dist_and_ver) < 2:
        return ""
    return dist_and_ver[-1]


def known_wheel_satisfies_requirement(requirement: str) -> bool:
    """True when a known local/CDN wheel exists and matches the version pin."""
    text = str(requirement or "").strip()
    if not text:
        return False
    try:
        from packaging.requirements import Requirement
        from packaging.version import Version
    except Exception:
        return False
    try:
        req = Requirement(text)
    except Exception:
        return False
    ver = known_wheel_version(req.name)
    if not ver:
        return False
    if not req.specifier:
        return True
    try:
        return Version(ver) in req.specifier
    except Exception:
        return False


def wheel_cache_dir() -> Path:
    try:
        from .paths import get_data_root

        root = get_data_root() / "wheel-cache"
    except Exception:
        root = Path(os.environ.get("TEMP") or os.getcwd()) / "TransubWheelCache"
    root.mkdir(parents=True, exist_ok=True)
    return root


def format_bytes_per_sec(bps: float | int | None) -> str:
    try:
        n = float(bps or 0)
    except (TypeError, ValueError):
        n = 0.0
    if n <= 0:
        return ""
    if n >= 1024 * 1024:
        return f"{n / (1024 * 1024):.1f} MB/s"
    if n >= 1024:
        return f"{n / 1024:.0f} KB/s"
    return f"{int(n)} B/s"


def format_probe_summary(probe_rows: Sequence[dict[str, Any]]) -> str:
    parts: list[str] = []
    for row in probe_rows:
        host = str(row.get("host") or "?")
        if not row.get("ok"):
            parts.append(f"{host}: 不可达")
            continue
        bps = format_bytes_per_sec(row.get("bytesPerSec"))
        ms = row.get("latencyMs")
        if bps:
            parts.append(f"{host}: {bps}")
        elif ms is not None:
            parts.append(f"{host}: {ms}ms")
        else:
            parts.append(f"{host}: ok")
    return "；".join(parts)


def _probe_index_latency(index_url: str, *, timeout: float) -> tuple[bool, float, int, str]:
    url = str(index_url or "").rstrip("/") + "/"
    t0 = time.perf_counter()
    try:
        req = urllib.request.Request(
            url,
            headers={"User-Agent": "transub-engine-mirror-probe"},
            method="GET",
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            chunk = resp.read(8192)
        ms = (time.perf_counter() - t0) * 1000.0
        return True, ms, len(chunk or b""), ""
    except (urllib.error.URLError, TimeoutError, OSError) as err:
        ms = (time.perf_counter() - t0) * 1000.0
        return False, ms, 0, str(err)[:240]
    except Exception as err:  # noqa: BLE001
        ms = (time.perf_counter() - t0) * 1000.0
        return False, ms, 0, str(err)[:240]


def _probe_package_throughput(
    index_url: str,
    *,
    timeout: float,
    sample_bytes: int,
) -> tuple[bool, float, int, float, str]:
    """
    Range-GET a known wheel path; return ok, latencyMs, sampleBytes, bytesPerSec, error.
    """
    url = wheel_url_for(index_url, PROBE_WHEEL_REL)
    t0 = time.perf_counter()
    try:
        req = urllib.request.Request(
            url,
            headers={
                "User-Agent": "transub-engine-mirror-probe",
                "Range": f"bytes=0-{max(0, sample_bytes - 1)}",
                "Accept": "*/*",
            },
            method="GET",
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = getattr(resp, "status", None) or resp.getcode()
            if status not in (200, 206):
                ms = (time.perf_counter() - t0) * 1000.0
                return False, ms, 0, 0.0, f"HTTP {status}"
            got = 0
            target = max(1024, int(sample_bytes))
            while got < target:
                chunk = resp.read(min(65536, target - got))
                if not chunk:
                    break
                got += len(chunk)
        ms = max(1.0, (time.perf_counter() - t0) * 1000.0)
        bps = (got / (ms / 1000.0)) if got > 0 else 0.0
        return got > 0, ms, got, round(bps, 1), ""
    except (urllib.error.URLError, TimeoutError, OSError) as err:
        ms = (time.perf_counter() - t0) * 1000.0
        return False, ms, 0, 0.0, str(err)[:240]
    except Exception as err:  # noqa: BLE001
        ms = (time.perf_counter() - t0) * 1000.0
        return False, ms, 0, 0.0, str(err)[:240]


def normalize_preferred_pip_mirror(value: str | None) -> str:
    """Empty / auto → '' (meaning speed-test). Otherwise trim trailing slash."""
    raw = str(value or "").strip()
    if not raw or raw.lower() in ("auto", "default", "probe", "测速", "自动", "自动测速"):
        return ""
    return raw.rstrip("/")


def resolve_preferred_mirror(
    prefer: str | None,
    *,
    mirrors: Sequence[tuple[str, str]] | None = None,
) -> tuple[str, str] | None:
    """
    Map UI id / host / index URL to a (indexUrl, host) pair from the catalog.

    Returns None for auto / empty / unknown.
    """
    key = normalize_preferred_pip_mirror(prefer)
    if not key:
        return None
    key_l = key.lower()
    targets = list(mirrors) if mirrors is not None else list(PIP_MIRRORS)
    # Catalog id first (stable UI values).
    for row in PIP_MIRROR_CATALOG:
        if str(row.get("id") or "").lower() == key_l:
            return (str(row["indexUrl"]), str(row["host"]))
    for index_url, host in targets:
        host_l = str(host or "").strip().lower()
        url_l = str(index_url or "").strip().rstrip("/").lower()
        if key_l == host_l or key_l == url_l or key_l in host_l or host_l in key_l:
            return (index_url, host)
        if key_l.startswith("http") and (key_l == url_l or url_l.startswith(key_l) or key_l.startswith(url_l)):
            return (index_url, host)
    return None


def preferred_mirror_from_env(
    *,
    mirrors: Sequence[tuple[str, str]] | None = None,
) -> tuple[str, str] | None:
    return resolve_preferred_mirror(
        os.environ.get(ENV_PREFERRED_PIP_MIRROR),
        mirrors=mirrors,
    )


@contextmanager
def temporary_preferred_pip_mirror(prefer: str | None):
    """
    Set TRANSUB_PIP_PREFERRED_MIRROR for the duration of a request / CLI call.

    ``None`` leaves the environment unchanged.
    ``\"\"`` / ``auto`` forces auto-probe (clears any ambient prefer).
    """
    if prefer is None:
        yield None
        return
    key = normalize_preferred_pip_mirror(prefer)
    prev = os.environ.get(ENV_PREFERRED_PIP_MIRROR)
    try:
        if key:
            os.environ[ENV_PREFERRED_PIP_MIRROR] = key
        else:
            os.environ.pop(ENV_PREFERRED_PIP_MIRROR, None)
        yield key
    finally:
        if prev is None:
            os.environ.pop(ENV_PREFERRED_PIP_MIRROR, None)
        else:
            os.environ[ENV_PREFERRED_PIP_MIRROR] = prev


def _pin_preferred_first(
    ordered: list[tuple[str, str]],
    prefer_pair: tuple[str, str] | None,
) -> list[tuple[str, str]]:
    if not prefer_pair:
        return ordered
    prefer_url, prefer_host = prefer_pair
    rest = [(u, h) for u, h in ordered if u != prefer_url]
    # User explicitly chose this host — clear demotion so it is tried first.
    try:
        _demoted_mirror_hosts.discard(str(prefer_host or "").strip().lower())
    except Exception:
        pass
    return [(prefer_url, prefer_host), *rest]


def probe_pip_mirrors(
    mirrors: Sequence[tuple[str, str]] | None = None,
    *,
    timeout: float = PROBE_TIMEOUT_SEC,
    sample_bytes: int = PROBE_SAMPLE_BYTES,
) -> list[dict[str, Any]]:
    """
    Rank mirrors by package-file throughput (primary) and index latency (fallback).

    Each row: ok, indexUrl, host, latencyMs, bytesPerSec, sampleBytes, error?
    """
    targets = list(mirrors) if mirrors is not None else list(PIP_MIRRORS)
    out: list[dict[str, Any]] = []
    for index_url, host in targets:
        item: dict[str, Any] = {
            "ok": False,
            "indexUrl": index_url,
            "host": host,
            "latencyMs": None,
            "bytesPerSec": 0,
            "sampleBytes": 0,
        }
        idx_ok, idx_ms, _idx_n, idx_err = _probe_index_latency(index_url, timeout=timeout)
        item["latencyMs"] = round(idx_ms, 1)
        thr_ok, thr_ms, thr_n, thr_bps, thr_err = _probe_package_throughput(
            index_url,
            timeout=timeout,
            sample_bytes=sample_bytes,
        )
        if thr_ok:
            item.update(
                {
                    "ok": True,
                    "latencyMs": round(min(idx_ms, thr_ms) if idx_ok else thr_ms, 1),
                    "bytesPerSec": thr_bps,
                    "sampleBytes": thr_n,
                }
            )
        elif idx_ok:
            # Index reachable but package sample failed (404 / block) — still usable
            # for pip -i, but rank below throughput winners.
            item.update(
                {
                    "ok": True,
                    "bytesPerSec": 0,
                    "sampleBytes": 0,
                    "error": thr_err or idx_err,
                }
            )
        else:
            item["error"] = thr_err or idx_err or "unreachable"
        out.append(item)
    return out


def order_pip_mirrors(
    probe_results: Sequence[dict[str, Any]] | None = None,
    *,
    mirrors: Sequence[tuple[str, str]] | None = None,
    prefer: str | tuple[str, str] | None = None,
) -> list[tuple[str, str]]:
    """
    Sort mirrors: demoted last, reachable first, then higher throughput, then lower latency.

    ``prefer`` (id / host / URL, or an ``(indexUrl, host)`` pair) is pinned first when
    resolvable. Empty / None means no pin (callers that want env prefer should pass
    ``preferred_mirror_from_env()`` or use ``resolve_pip_mirror_order``).
    When ``prefer`` is set and ``probe_results`` is None, skip probing and return
    catalog order with the preferred mirror first (manual switch path).
    """
    targets = list(mirrors) if mirrors is not None else list(PIP_MIRRORS)
    if isinstance(prefer, tuple) and len(prefer) >= 2:
        prefer_pair: tuple[str, str] | None = (str(prefer[0]), str(prefer[1]))
    else:
        prefer_pair = resolve_preferred_mirror(str(prefer or ""), mirrors=targets)

    if prefer_pair and probe_results is None:
        return _pin_preferred_first(list(targets), prefer_pair)

    results = list(probe_results) if probe_results is not None else probe_pip_mirrors(targets)
    demoted = {h.lower() for h in _demoted_mirror_hosts}
    ranked = sorted(
        results,
        key=lambda r: (
            1 if str(r.get("host") or "").strip().lower() in demoted else 0,
            0 if r.get("ok") else 1,
            # Higher throughput first (negate).
            -float(r.get("bytesPerSec") or 0),
            float(r["latencyMs"]) if r.get("latencyMs") is not None else 1e12,
            str(r.get("host") or ""),
        ),
    )
    ordered: list[tuple[str, str]] = []
    seen: set[str] = set()
    for row in ranked:
        index_url = str(row.get("indexUrl") or "").strip()
        host = str(row.get("host") or "").strip()
        if not index_url or not host or index_url in seen:
            continue
        seen.add(index_url)
        ordered.append((index_url, host))
    for index_url, host in targets:
        if index_url not in seen:
            ordered.append((index_url, host))
            seen.add(index_url)
    ordered = ordered or list(targets)
    return _pin_preferred_first(ordered, prefer_pair)


def resolve_pip_mirror_order(
    *,
    prefer: str | None = None,
    mirrors: Sequence[tuple[str, str]] | None = None,
) -> tuple[list[tuple[str, str]], list[dict[str, Any]], bool]:
    """
    Build install order: manual prefer skips probe; otherwise probe then rank.

    Returns ``(ordered, probe_rows, used_prefer)``.
    """
    targets = list(mirrors) if mirrors is not None else list(PIP_MIRRORS)
    prefer_key = normalize_preferred_pip_mirror(prefer)
    if prefer is None and not prefer_key:
        # Fall back to env when caller did not pass an explicit prefer string.
        env_pair = preferred_mirror_from_env(mirrors=targets)
        if env_pair:
            prefer_key = env_pair[1]
    prefer_pair = resolve_preferred_mirror(prefer_key, mirrors=targets) if prefer_key else None
    if prefer_pair:
        ordered = order_pip_mirrors(None, mirrors=targets, prefer=prefer_pair)
        return ordered, [], True
    probe_rows = probe_pip_mirrors(targets)
    ordered = order_pip_mirrors(probe_rows, mirrors=targets, prefer=None)
    return ordered, probe_rows, False


def best_probe_bytes_per_sec(probe_rows: Sequence[dict[str, Any]]) -> float:
    best = 0.0
    for row in probe_rows or []:
        if not row.get("ok"):
            continue
        try:
            best = max(best, float(row.get("bytesPerSec") or 0))
        except (TypeError, ValueError):
            continue
    return best


def _wheel_distribution_name(wheel_path: str) -> str:
    """PEP 427 wheel filename → distribution name (``numpy-2.4.6-…whl`` → ``numpy``)."""
    stem = Path(wheel_path).name
    if stem.lower().endswith(".whl"):
        stem = stem[:-4]
    part = stem.split("-", 1)[0].strip()
    return part.replace("_", "-").lower() if part else ""


def _dist_info_has_record(dist_name: str) -> bool | None:
    """
    True when RECORD exists; False when the dist is installed but RECORD is missing;
    None when the distribution is not installed / cannot be resolved.
    """
    name = str(dist_name or "").strip()
    if not name:
        return None
    try:
        from importlib.metadata import PackageNotFoundError, distribution

        dist = distribution(name)
    except PackageNotFoundError:
        return None
    except Exception:
        return None
    try:
        record = Path(str(dist.locate_file("RECORD")))
        return bool(record.is_file())
    except Exception:
        return False


def _pip_log_is_uninstall_no_record(log: str) -> bool:
    low = str(log or "").lower()
    return "uninstall-no-record-file" in low or (
        "no record file" in low and "uninstall" in low
    )


def install_local_wheel_files(
    wheel_paths: Sequence[str],
    *,
    on_progress: ProgressCb | None = None,
    detail_prefix: str = "本地安装",
    timeout_sec: float = 1800.0,
) -> dict[str, Any]:
    """
    Install already-downloaded .whl files with **no network** (``--no-index --no-deps``).

    Using ``pip install --upgrade <paths>`` without ``--no-index`` makes pip contact
    PyPI mirrors again and routinely hangs 10+ minutes after a successful download.

    Broken site-packages (dist-info without RECORD) fail ``--force-reinstall`` with
    ``uninstall-no-record-file``; we detect that and retry with ``--ignore-installed``.
    """
    import subprocess
    import sys
    import threading

    paths = [str(p) for p in wheel_paths if str(p).strip()]
    paths = [p for p in paths if Path(p).is_file()]
    if not paths:
        return {"ok": False, "error": "没有可安装的本地 .whl 文件"}

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    names = [Path(p).name for p in paths]
    short = ", ".join(names[:3]) + ("…" if len(names) > 3 else "")
    emit(
        {
            "type": "progress",
            "stage": "install",
            "percent": 78,
            "detail": f"{detail_prefix}（离线，{len(paths)} 个包：{short}）…",
            "downloadedBytes": None,
            "totalBytes": None,
            "bytesPerSecond": 0,
        }
    )

    # Prefer --ignore-installed when any target already has broken dist-info
    # (missing RECORD). --force-reinstall would otherwise abort before writing.
    broken_record = False
    for p in paths:
        dist_name = _wheel_distribution_name(p)
        if dist_name and _dist_info_has_record(dist_name) is False:
            broken_record = True
            _log.warning(
                "install_local_wheel_files: %s dist-info missing RECORD; "
                "using --ignore-installed",
                dist_name,
            )
            break

    def _run_once(*, ignore_installed: bool) -> dict[str, Any]:
        mode_flags = (
            ["--ignore-installed"]
            if ignore_installed
            else ["--force-reinstall"]
        )
        cmd = [
            sys.executable,
            "-u",
            "-m",
            "pip",
            "install",
            *mode_flags,
            "--no-deps",
            "--no-index",
            "--no-cache-dir",
            "--disable-pip-version-check",
            *paths,
        ]
        _log.info("install_local_wheel_files: %s", " ".join(cmd))
        env = os.environ.copy()
        env["PYTHONUNBUFFERED"] = "1"
        # Ensure pip cannot pick up a user index URL / proxy that reintroduces network waits.
        env.pop("PIP_INDEX_URL", None)
        env.pop("PIP_EXTRA_INDEX_URL", None)
        env["PIP_NO_INDEX"] = "1"

        try:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                encoding="utf-8",
                errors="replace",
                env=env,
                bufsize=1,
            )
        except OSError as err:
            return {"ok": False, "error": str(err)}

        chunks: list[str] = []
        started = time.monotonic()
        stop_hb = threading.Event()

        def _hb() -> None:
            while not stop_hb.wait(2.0):
                elapsed = int(time.monotonic() - started)
                emit(
                    {
                        "type": "progress",
                        "stage": "install",
                        "percent": min(95, 78 + elapsed // 8),
                        "detail": f"{detail_prefix}解压写入中…（已 {elapsed} 秒，大包可能需数分钟）",
                    }
                )

        hb = threading.Thread(target=_hb, name="local-whl-install-hb", daemon=True)
        hb.start()
        code = 1
        try:
            assert proc.stdout is not None
            while True:
                if timeout_sec > 0 and (time.monotonic() - started) > timeout_sec:
                    try:
                        proc.kill()
                    except Exception:
                        pass
                    return {
                        "ok": False,
                        "error": (
                            f"本地安装超时（{int(timeout_sec)} 秒）。"
                            "wheel 已在缓存，可重试或改用手动安装。"
                        ),
                        "logTail": "".join(chunks)[-1200:],
                    }
                line = proc.stdout.readline()
                if not line:
                    break
                text = line.strip()
                if text:
                    chunks.append(text + "\n")
                    if len(chunks) > 120:
                        chunks = chunks[-80:]
                    low = text.lower()
                    if "installing" in low or "processing" in low or ".whl" in low:
                        emit(
                            {
                                "type": "progress",
                                "stage": "install",
                                "percent": min(
                                    94, 80 + int((time.monotonic() - started) / 6)
                                ),
                                "detail": f"{detail_prefix}：{text[:100]}",
                            }
                        )
            code = proc.wait(timeout=60)
        except Exception as err:
            try:
                proc.kill()
            except Exception:
                pass
            return {
                "ok": False,
                "error": str(err),
                "logTail": "".join(chunks)[-1200:],
            }
        finally:
            stop_hb.set()
            try:
                hb.join(timeout=1.0)
            except Exception:
                pass

        log_tail = "".join(chunks)[-1200:]
        if code == 0:
            emit(
                {
                    "type": "progress",
                    "stage": "install",
                    "percent": 96,
                    "detail": f"{detail_prefix}完成",
                }
            )
            return {
                "ok": True,
                "logTail": log_tail,
                "paths": paths,
                "ignoreInstalled": ignore_installed,
            }
        low = log_tail.lower()
        # Parent process often already imported native wheels; Windows then denies
        # overwrite (WinError 5) during --force-reinstall / --ignore-installed.
        if "winerror 5" in low or "拒绝访问" in log_tail or "access is denied" in low:
            return {
                "ok": False,
                "code": "EXTRAS_LOCKED_IN_PROCESS",
                "error": (
                    f"本地 pip 安装失败（exit {code}）：文件被占用/拒绝访问。"
                    "请先停止引擎后再重试，或改用手动安装。"
                ),
                "logTail": log_tail,
            }
        err_line = ""
        for line in reversed(log_tail.splitlines()):
            s = line.strip()
            if not s:
                continue
            if (
                s.lower().startswith("error")
                or "winerror" in s.lower()
                or "拒绝访问" in s
            ):
                err_line = s[:240]
                break
        detail = f"：{err_line}" if err_line else ""
        return {
            "ok": False,
            "error": f"本地 pip 安装失败（exit {code}）{detail}",
            "logTail": log_tail,
            "uninstallNoRecord": _pip_log_is_uninstall_no_record(log_tail),
        }

    first = _run_once(ignore_installed=broken_record)
    if first.get("ok"):
        return first
    # --force-reinstall hit a broken RECORD we did not detect up front: retry once.
    if (
        not broken_record
        and first.get("uninstallNoRecord")
        and first.get("code") != "EXTRAS_LOCKED_IN_PROCESS"
    ):
        emit(
            {
                "type": "progress",
                "stage": "install",
                "percent": 79,
                "detail": (
                    f"{detail_prefix}：检测到损坏的包元数据（无 RECORD），"
                    "改用覆盖安装重试…"
                ),
            }
        )
        _log.warning(
            "install_local_wheel_files: uninstall-no-record-file; "
            "retrying with --ignore-installed"
        )
        retry = _run_once(ignore_installed=True)
        if retry.get("ok"):
            retry["repairedNoRecord"] = True
            return retry
        return retry
    return first


def plan_parallel_ranges(
    total_bytes: int,
    *,
    connections: int = DOWNLOAD_PARALLEL_CONN,
    part_min: int = DOWNLOAD_PARALLEL_PART_MIN,
) -> list[tuple[int, int]]:
    """
    Split ``[0, total)`` into inclusive (start, end) byte ranges for parallel GET.

    Returns a single full-range tuple when the object is too small to split.
    """
    total = int(total_bytes or 0)
    if total <= 0:
        return []
    conn = max(1, int(connections or 1))
    min_part = max(64 * 1024, int(part_min or 0))
    # Cap workers so each part stays reasonably large.
    max_by_size = max(1, total // min_part)
    conn = max(1, min(conn, max_by_size))
    if conn <= 1 or total < DOWNLOAD_PARALLEL_MIN_BYTES:
        return [(0, total - 1)]
    size = total // conn
    ranges: list[tuple[int, int]] = []
    start = 0
    for i in range(conn):
        end = (total - 1) if i == conn - 1 else (start + size - 1)
        ranges.append((start, end))
        start = end + 1
    return ranges


def _probe_download_size(url: str, *, timeout: float = 30.0) -> dict[str, Any]:
    """Return total size + whether the server honors Range (via bytes=0-0 probe)."""
    headers = {
        "User-Agent": "transub-engine-wheel-dl",
        "Accept": "*/*",
        "Range": "bytes=0-0",
    }
    req = urllib.request.Request(str(url), headers=headers, method="GET")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = getattr(resp, "status", None) or resp.getcode()
            # Drain at most one byte so the connection can close cleanly.
            try:
                resp.read(8)
            except Exception:
                pass
            cr = resp.headers.get("Content-Range") or ""
            cl = resp.headers.get("Content-Length")
            accept = (resp.headers.get("Accept-Ranges") or "").lower()
            total = 0
            if cr.startswith("bytes ") and "/" in cr:
                try:
                    total = int(cr.rsplit("/", 1)[-1])
                except ValueError:
                    total = 0
            if total <= 0 and cl and status == 200:
                try:
                    total = int(cl)
                except ValueError:
                    total = 0
            ranged = status == 206 or (total > 1 and "bytes" in accept)
            return {
                "ok": status in (200, 206),
                "status": int(status or 0),
                "total": int(total or 0),
                "acceptRanges": ranged,
            }
    except Exception as err:
        return {"ok": False, "error": str(err)[:300], "total": 0, "acceptRanges": False}


def _download_byte_range(
    url: str,
    dest: Path,
    start: int,
    end: int,
    *,
    timeout: float,
    stop_event: threading.Event,
    on_bytes: Callable[[int], None] | None = None,
) -> None:
    """Write bytes ``start..end`` inclusive into ``dest`` (pre-sized file)."""
    headers = {
        "User-Agent": "transub-engine-wheel-dl",
        "Accept": "*/*",
        "Range": f"bytes={int(start)}-{int(end)}",
    }
    req = urllib.request.Request(str(url), headers=headers, method="GET")
    expected = int(end) - int(start) + 1
    got = 0
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        status = getattr(resp, "status", None) or resp.getcode()
        if status not in (200, 206):
            raise urllib.error.HTTPError(url, status, f"HTTP {status}", resp.headers, None)
        if status == 200:
            # Server ignored Range — cannot multi-conn safely.
            raise MirrorStallError("STALL: 服务器未支持分片 Range")
        with open(dest, "r+b") as fh:
            fh.seek(int(start))
            while got < expected:
                if stop_event.is_set():
                    raise MirrorStallError("STALL: 分片下载已取消")
                need = min(DOWNLOAD_READ_CHUNK, expected - got)
                chunk = resp.read(need)
                if not chunk:
                    break
                fh.write(chunk)
                n = len(chunk)
                got += n
                if on_bytes:
                    on_bytes(n)
    if got != expected:
        raise MirrorStallError(f"STALL: 分片不完整 {got}/{expected} @ {start}-{end}")


def _download_url_parallel(
    url: str,
    dest: Path,
    part: Path,
    total: int,
    *,
    on_progress: ProgressCb | None,
    host: str,
    detail_prefix: str,
    stall_sec: float,
    timeout: float,
    max_sec: float,
    min_bps: float,
) -> dict[str, Any]:
    ranges = plan_parallel_ranges(total)
    if len(ranges) <= 1:
        return {"ok": False, "error": "parallel_not_applicable"}

    # Fresh parallel attempt — discard any single-stream partial.
    try:
        if part.exists():
            part.unlink()
    except OSError:
        pass

    # Pre-allocate so each worker can seek/write its own handle.
    with open(part, "wb") as fh:
        if total > 1:
            fh.seek(total - 1)
            fh.write(b"\0")
        else:
            fh.write(b"\0")

    lock = threading.Lock()
    stop_event = threading.Event()
    written = 0
    t0 = time.monotonic()
    last_data_at = t0
    last_emit = 0.0
    errors: list[str] = []

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    def on_bytes(n: int) -> None:
        nonlocal written, last_data_at, last_emit
        now = time.monotonic()
        with lock:
            written += int(n)
            last_data_at = now
            cur = written
            emit_due = (now - last_emit) >= 0.35
            if emit_due:
                last_emit = now
        if emit_due:
            elapsed = max(0.001, now - t0)
            speed = cur / elapsed
            prefix = detail_prefix or "下载运行库"
            name = dest.name
            if len(name) > 42:
                name = name[:39] + "…"
            emit(
                {
                    "type": "progress",
                    "stage": "download",
                    "detail": f"{prefix}（{host} · {len(ranges)} 线程）· {name}",
                    "mirror": host,
                    "downloadedBytes": int(cur),
                    "totalBytes": int(total),
                    "bytesPerSecond": round(speed, 1),
                    "parallelConnections": len(ranges),
                    "suggestManual": bool(
                        speed > 0 and speed < 80_000 and cur > 2 * 1024 * 1024
                    ),
                }
            )

    def worker(span: tuple[int, int]) -> None:
        start, end = span
        try:
            _download_byte_range(
                url,
                part,
                start,
                end,
                timeout=timeout,
                stop_event=stop_event,
                on_bytes=on_bytes,
            )
        except Exception as err:
            stop_event.set()
            with lock:
                errors.append(str(err)[:300])
            raise

    # Watchdog while workers run.
    with ThreadPoolExecutor(max_workers=len(ranges)) as pool:
        futures = [pool.submit(worker, span) for span in ranges]
        pending = set(futures)
        while pending:
            now = time.monotonic()
            with lock:
                cur = written
                idle = now - last_data_at
            reason = transfer_should_abort(
                elapsed_sec=now - t0,
                session_bytes=cur,
                last_progress_age_sec=idle,
                stall_sec=stall_sec,
                min_bps=min_bps,
                max_sec=max_sec,
            )
            if reason:
                stop_event.set()
                for fut in pending:
                    fut.cancel()
                raise MirrorTooSlowError(f"{reason}（{host or url}）")
            done_now = {f for f in pending if f.done()}
            for fut in done_now:
                pending.discard(fut)
                exc = fut.exception()
                if exc is not None:
                    stop_event.set()
                    for other in pending:
                        other.cancel()
                    if isinstance(exc, MirrorStallError):
                        raise exc
                    raise MirrorStallError(str(exc)[:400]) from exc
            if pending:
                time.sleep(0.2)

    if errors and written < total:
        return {"ok": False, "error": errors[0], "path": str(part), "bytes": written}
    if written < total:
        # Some CDNs don't count overlapping reads — verify file size on disk.
        try:
            disk = part.stat().st_size
        except OSError:
            disk = written
        if disk < total:
            return {
                "ok": False,
                "error": f"incomplete {disk}/{total}",
                "path": str(part),
                "bytes": disk,
            }

    try:
        if dest.exists():
            dest.unlink()
    except OSError:
        pass
    part.replace(dest)
    return {
        "ok": True,
        "path": str(dest),
        "bytes": total,
        "host": host,
        "parallelConnections": len(ranges),
    }


def download_url_resumable(
    url: str,
    dest: Path,
    *,
    on_progress: ProgressCb | None = None,
    host: str = "",
    detail_prefix: str = "",
    stall_sec: float = DOWNLOAD_STALL_SEC,
    timeout: float = 30.0,
    expected_total: int | None = None,
    max_sec: float = DOWNLOAD_MIRROR_MAX_SEC,
    min_bps: float = DOWNLOAD_MIN_BPS,
    parallel: bool | None = None,
) -> dict[str, Any]:
    """
    Download ``url`` to ``dest`` with Range resume and stall / too-slow detection.

    Large objects use multi-connection Range GETs when the server supports them
    (often 5–20× faster than single-stream pip/urllib on CN mirrors). Partial
    bytes live in ``dest.with_suffix(dest.suffix + '.part')``.
    """
    dest = Path(dest)
    dest.parent.mkdir(parents=True, exist_ok=True)
    part = dest.with_suffix(dest.suffix + ".part")
    if dest.is_file() and dest.stat().st_size > 1024 and not part.exists():
        return {"ok": True, "path": str(dest), "skipped": True, "bytes": dest.stat().st_size}

    existing = part.stat().st_size if part.is_file() else 0
    want_parallel = parallel if parallel is not None else True

    # Fresh large downloads: try multi-conn first (skip when resuming a .part).
    if want_parallel and existing <= 0:
        probe = _probe_download_size(url, timeout=min(15.0, float(timeout) or 15.0))
        total_guess = int(probe.get("total") or expected_total or 0)
        if (
            probe.get("ok")
            and probe.get("acceptRanges")
            and total_guess >= DOWNLOAD_PARALLEL_MIN_BYTES
        ):
            try:
                result = _download_url_parallel(
                    url,
                    dest,
                    part,
                    total_guess,
                    on_progress=on_progress,
                    host=host,
                    detail_prefix=detail_prefix,
                    stall_sec=stall_sec,
                    timeout=timeout,
                    max_sec=max_sec,
                    min_bps=min_bps,
                )
                if result.get("ok"):
                    return result
                _log.info(
                    "parallel download fallback → single: %s",
                    result.get("error") or "unknown",
                )
            except MirrorTooSlowError:
                # This mirror is too slow even with multi-conn — let caller rotate.
                raise
            except MirrorStallError as err:
                _log.info(
                    "parallel download stalled (%s); falling back to single stream",
                    err,
                )
                try:
                    if part.exists():
                        part.unlink()
                except OSError:
                    pass
            except Exception as err:
                _log.info("parallel download failed (%s); falling back to single stream", err)
                try:
                    if part.exists():
                        part.unlink()
                except OSError:
                    pass

    return _download_url_single(
        url,
        dest,
        part,
        on_progress=on_progress,
        host=host,
        detail_prefix=detail_prefix,
        stall_sec=stall_sec,
        timeout=timeout,
        expected_total=expected_total,
        max_sec=max_sec,
        min_bps=min_bps,
    )


def _download_url_single(
    url: str,
    dest: Path,
    part: Path,
    *,
    on_progress: ProgressCb | None = None,
    host: str = "",
    detail_prefix: str = "",
    stall_sec: float = DOWNLOAD_STALL_SEC,
    timeout: float = 30.0,
    expected_total: int | None = None,
    max_sec: float = DOWNLOAD_MIRROR_MAX_SEC,
    min_bps: float = DOWNLOAD_MIN_BPS,
) -> dict[str, Any]:
    existing = part.stat().st_size if part.is_file() else 0
    headers = {
        "User-Agent": "transub-engine-wheel-dl",
        "Accept": "*/*",
    }
    if existing > 0:
        headers["Range"] = f"bytes={existing}-"

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    t0 = time.monotonic()
    last_data_at = t0
    written = existing
    total = int(expected_total or 0)
    session_start_bytes = existing

    try:
        req = urllib.request.Request(str(url), headers=headers, method="GET")
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = getattr(resp, "status", None) or resp.getcode()
            if status == 200 and existing > 0:
                # Server ignored Range — restart.
                existing = 0
                written = 0
                session_start_bytes = 0
                try:
                    part.unlink(missing_ok=True)  # type: ignore[call-arg]
                except TypeError:
                    if part.exists():
                        part.unlink()
                except OSError:
                    pass
            elif status not in (200, 206):
                raise urllib.error.HTTPError(url, status, f"HTTP {status}", resp.headers, None)

            cl = resp.headers.get("Content-Length")
            cr = resp.headers.get("Content-Range") or ""
            if cr.startswith("bytes ") and "/" in cr:
                try:
                    total = int(cr.rsplit("/", 1)[-1])
                except ValueError:
                    pass
            elif cl and status == 206:
                try:
                    total = existing + int(cl)
                except ValueError:
                    pass
            elif cl and status == 200:
                try:
                    total = int(cl)
                except ValueError:
                    pass

            mode = "ab" if existing > 0 and status == 206 else "wb"
            if mode == "wb":
                written = 0
                session_start_bytes = 0
            last_emit = 0.0
            with open(part, mode) as fh:
                while True:
                    now = time.monotonic()
                    session_bytes = max(0, written - session_start_bytes)
                    reason = transfer_should_abort(
                        elapsed_sec=now - t0,
                        session_bytes=session_bytes,
                        last_progress_age_sec=now - last_data_at,
                        stall_sec=stall_sec,
                        min_bps=min_bps,
                        max_sec=max_sec,
                    )
                    if reason:
                        raise MirrorTooSlowError(f"{reason}（{host or url}）")
                    try:
                        chunk = resp.read(DOWNLOAD_READ_CHUNK)
                    except TimeoutError as err:
                        raise MirrorStallError(
                            f"STALL: 读取超时（{host or url}）: {err}"
                        ) from err
                    except OSError as err:
                        raise MirrorStallError(
                            f"STALL: 连接中断（{host or url}）: {err}"
                        ) from err
                    if not chunk:
                        break
                    fh.write(chunk)
                    written += len(chunk)
                    last_data_at = time.monotonic()
                    now = time.monotonic()
                    if now - last_emit >= 0.4:
                        last_emit = now
                        elapsed = max(0.001, now - t0)
                        session = max(0, written - session_start_bytes)
                        speed = session / elapsed
                        prefix = detail_prefix or "下载运行库"
                        name = dest.name
                        if len(name) > 42:
                            name = name[:39] + "…"
                        emit(
                            {
                                "type": "progress",
                                "stage": "download",
                                "detail": f"{prefix}（{host}）· {name}",
                                "mirror": host,
                                "downloadedBytes": int(written),
                                "totalBytes": int(total) if total > 0 else None,
                                "bytesPerSecond": round(speed, 1),
                                "suggestManual": bool(
                                    speed > 0 and speed < 80_000 and written > 2 * 1024 * 1024
                                ),
                            }
                        )
    except MirrorStallError:
        raise
    except urllib.error.HTTPError as err:
        return {"ok": False, "error": f"HTTP {err.code}", "path": str(part), "bytes": written}
    except (urllib.error.URLError, TimeoutError, OSError) as err:
        return {"ok": False, "error": str(err)[:400], "path": str(part), "bytes": written}

    if written <= 0:
        return {"ok": False, "error": "empty download", "path": str(part), "bytes": 0}
    if total > 0 and written < total:
        return {
            "ok": False,
            "error": f"incomplete {written}/{total}",
            "path": str(part),
            "bytes": written,
        }

    try:
        if dest.exists():
            dest.unlink()
    except OSError:
        pass
    part.replace(dest)
    return {"ok": True, "path": str(dest), "bytes": written, "host": host}


def torch_cuda_wheel_url(base_url: str, filename: str) -> str:
    """Build a direct .whl URL for PyTorch CUDA flat indexes."""
    base = str(base_url or "").rstrip("/") + "/"
    fname = str(filename or "").strip()
    if "pytorch.org" in base.lower():
        fname = quote(fname, safe="")
    return base + fname


def download_torch_cuda_wheels(
    *,
    on_progress: ProgressCb | None = None,
    detail_prefix: str = "CUDA PyTorch",
    stall_sec: float = DOWNLOAD_STALL_SEC,
    max_sec: float = TORCH_CUDA_DOWNLOAD_MAX_SEC,
    variant: str | None = None,
) -> dict[str, Any]:
    """
    Download pinned torch + torchaudio wheels via resumable HTTP.

    Blackwell (RTX 50xx) uses cu128 (driver CUDA 12.x) or cu130 (driver CUDA 13+);
    older GPUs use cu126 (Aliyun mirror first).
    """
    cfg = resolve_torch_cuda_variant_config(variant)
    wheel_files = tuple(cfg.get("wheel_files") or ())
    direct_sources = tuple(cfg.get("direct_sources") or ())
    label = str(cfg.get("label") or "cu126")
    cache = wheel_cache_dir()
    last_error = ""

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    for base_url, host in direct_sources:
        emit(
            {
                "type": "progress",
                "stage": "torch_cuda",
                "detail": (
                    f"正在直链下载{detail_prefix}（{label}，{host}，约 2.5GB，支持断点续传）…"
                ),
                "mirror": base_url,
                "totalBytes": TORCH_CUDA_SIZE_HINT_BYTES,
                "torchCudaVariant": label,
            }
        )
        paths: list[str] = []
        failed = False
        for filename in wheel_files:
            dest = cache / filename
            url = torch_cuda_wheel_url(base_url, filename)
            try:
                result = download_url_resumable(
                    url,
                    dest,
                    on_progress=on_progress,
                    host=host,
                    detail_prefix=detail_prefix,
                    stall_sec=stall_sec,
                    max_sec=max_sec,
                )
            except MirrorStallError as err:
                last_error = str(err)
                failed = True
                break
            if not result.get("ok"):
                last_error = str(result.get("error") or "download failed")
                failed = True
                break
            paths.append(str(result["path"]))
        if failed:
            emit(
                {
                    "type": "progress",
                    "stage": "torch_cuda",
                    "detail": f"镜像 {host} 下载失败/停滞，自动切换下一源…",
                    "mirror": base_url,
                    "suggestManual": True,
                    "totalBytes": TORCH_CUDA_SIZE_HINT_BYTES,
                }
            )
            continue
        return {
            "ok": True,
            "localPaths": paths,
            "host": host,
            "source": base_url,
            "torchCudaVariant": label,
        }

    return {
        "ok": False,
        "error": last_error or "所有 CUDA PyTorch 直链源均失败",
        "stalled": "STALL:" in str(last_error or ""),
        "torchCudaVariant": label,
    }


def download_known_wheels(
    package_names: Sequence[str],
    *,
    index_url: str,
    host: str,
    on_progress: ProgressCb | None = None,
    detail_prefix: str = "下载运行库",
    stall_sec: float = DOWNLOAD_STALL_SEC,
) -> dict[str, Any]:
    """
    Download known-hash wheels for ``package_names`` from one mirror into wheel-cache.

    Returns ok + localPaths, or ok=False with error (caller should try next mirror).
    """
    cache = wheel_cache_dir()
    paths: list[str] = []
    missing: list[str] = []
    for raw in package_names:
        name = str(raw or "").strip().lower().replace("_", "-")
        # Strip version pins: "numpy>=1.24" → try "numpy"
        base = name.split(">", 1)[0].split("<", 1)[0].split("=", 1)[0].split("[", 1)[0].strip()
        rel = known_wheel_rel(base)
        if not rel:
            missing.append(base or name)
            continue
        filename = rel.rsplit("/", 1)[-1]
        dest = cache / filename
        url = wheel_url_for(index_url, rel)
        try:
            result = download_url_resumable(
                url,
                dest,
                on_progress=on_progress,
                host=host,
                detail_prefix=detail_prefix,
                stall_sec=stall_sec,
            )
        except MirrorStallError as err:
            note_mirror_denied(host)  # soft demote for this process? skip — stall ≠ 403
            return {
                "ok": False,
                "stalled": True,
                "error": str(err),
                "host": host,
                "localPaths": paths,
            }
        if not result.get("ok"):
            return {
                "ok": False,
                "error": result.get("error") or "download failed",
                "host": host,
                "localPaths": paths,
                "package": base,
            }
        paths.append(str(result["path"]))

    if missing and not paths:
        return {"ok": False, "error": f"no known wheel URLs for: {', '.join(missing)}", "missing": missing}
    return {
        "ok": True,
        "localPaths": paths,
        "missing": missing,
        "host": host,
    }
